using GrifballWebApp.Domain.Archive;

namespace GrifballWebApp.Historical.Sources;

/// <summary>
/// Every source of the historical archive (what the former Node archive-tools listed in download-all.mjs, with what
/// seasons-config.json and extract-waypoint-matches.mjs said to read from each). <c>HistoricalSourceService.EnsureCatalog</c> writes them to
/// HistoricalSources at runtime: new ones are added and the catalog's fields kept current, while Enabled and the fetch
/// status stay the database's. Dead sources are kept, never downloaded, so the list says what once existed.
/// Left out: the Wayback capture of playgrifball.com (the old site, nothing the import reads).
/// </summary>
public static class HistoricalSourceCatalog
{
    /// <summary>A catalog entry: a source row without its runtime state.</summary>
    public sealed class Entry
    {
        public required string HistoricalSourceID { get; init; }
        public required string Category { get; init; }
        public int? Year { get; init; }
        public required string Title { get; init; }
        public required string Url { get; init; }
        public HistoricalSourceKind Kind { get; init; }
        public string? SheetKey { get; init; }
        public string? Gid { get; init; }
        public string? CsvSheetName { get; init; }
        public string? WaybackTimestamp { get; init; }
        public string? League { get; init; }
        public string? GameVersion { get; init; }
        public string? Format { get; init; }
        /// <summary>Whether it is downloaded once alive. A dead entry leaves it at true, so reviving one is the single
        /// <see cref="IsDead"/> edit (a catalog test keeps it so).</summary>
        public bool Enabled { get; init; } = true;
        public bool IsDead { get; init; }
        public HistoricalSourceConfig? Config { get; init; }

        /// <summary>Its catalog fields, as its row keeps them.</summary>
        public HistoricalSourceListing ToListing() => new()
        {
            Category = Category,
            Year = Year,
            Title = Title,
            Url = Url,
            Kind = Kind,
            SheetKey = SheetKey,
            Gid = Gid,
            CsvSheetName = CsvSheetName,
            WaybackTimestamp = WaybackTimestamp,
            League = League,
            GameVersion = GameVersion,
            Format = Format,
            IsDead = IsDead,
            Config = Config?.ToJson(),
        };
    }

